import{c as r,Q as i,j as s,m as l}from"./chunks/framework.BPmZ9ESu.js";const h=JSON.parse(`{"title":"Rechercher l'information sur la profession","description":"Trouver des sources utiles et fiables sur les professions et les milieux informatiques","frontmatter":{"title":"Rechercher l'information sur la profession","description":"Trouver des sources utiles et fiables sur les professions et les milieux informatiques"},"headers":[],"relativePath":"modules/04-analyse-info/01-recherche.md","filePath":"modules/04-analyse-info/01-recherche.md"}`),t={name:"modules/04-analyse-info/01-recherche.md"};function a(o,e,n,u,c,p){return i(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="rechercher-l-information-sur-la-profession" tabindex="-1">Rechercher l&#39;information sur la profession <a class="header-anchor" href="#rechercher-l-information-sur-la-profession" aria-label="Permalink to &quot;Rechercher l&#39;information sur la profession&quot;">​</a></h1><p>Avant d&#39;analyser une entreprise ou un poste, il faut d&#39;abord savoir où chercher.</p><p>Le but n&#39;est pas d&#39;accumuler beaucoup de liens. Le but est de trouver des sources utiles, variées et fiables.</p><h2 id="quelles-sources-utiliser" tabindex="-1">Quelles sources utiliser <a class="header-anchor" href="#quelles-sources-utiliser" aria-label="Permalink to &quot;Quelles sources utiliser&quot;">​</a></h2><p>Voici quelques sources utiles pour ce module :</p><ul><li>le site officiel d&#39;une entreprise</li><li>la section carrières (habituellement en bas de page)</li><li>une offre d&#39;emploi publiée par l&#39;entreprise (Indeed, LinkedIn, Glassdoor)</li><li>un répertoire d&#39;entreprises</li><li>un répertoire de professions</li><li>un site gouvernemental ou institutionnel</li><li>une source liée à une visite ou à une conférence</li></ul><h3 id="quelques-ressources-utiles" tabindex="-1">Quelques ressources utiles <a class="header-anchor" href="#quelques-ressources-utiles" aria-label="Permalink to &quot;Quelques ressources utiles&quot;">​</a></h3><h4 id="repertoires-d-entreprises" tabindex="-1">Répertoires d&#39;entreprises <a class="header-anchor" href="#repertoires-d-entreprises" aria-label="Permalink to &quot;Répertoires d&#39;entreprises&quot;">​</a></h4><ul><li><a href="https://www.agenceswebduquebec.com/agences/liste/quebec" target="_blank" rel="noreferrer">Agences Web du Québec — liste d&#39;agences à Québec</a></li><li><a href="https://repertoiredesentreprisesduquebec.ca/category/informatique-web/" target="_blank" rel="noreferrer">Mon Québec — informatique web</a></li><li><a href="https://www.quebec.ca/entreprises-et-travailleurs-autonomes/obtenir-renseignements-entreprise/recherche-registre-entreprises/acceder-registre-entreprises" target="_blank" rel="noreferrer">Québec.ca — Registre des entreprises</a></li></ul><h4 id="repertoires-de-professions" tabindex="-1">Répertoires de professions <a class="header-anchor" href="#repertoires-de-professions" aria-label="Permalink to &quot;Répertoires de professions&quot;">​</a></h4><ul><li><p><a href="https://www.jobboom.com/fr/metiers/technologies-medias-numeriques" target="_blank" rel="noreferrer">Jobboom — métiers en technologies et médias numériques</a></p></li><li><p><a href="https://www.quebec.ca/gouvernement/travailler-gouvernement/emplois-fonction-publique/domaines-emploi/technologies-information/technicien-informatique" target="_blank" rel="noreferrer">Québec.ca — Technologies de l&#39;information</a></p></li></ul><h4 id="sources-gouvernementales" tabindex="-1">Sources gouvernementales <a class="header-anchor" href="#sources-gouvernementales" aria-label="Permalink to &quot;Sources gouvernementales&quot;">​</a></h4><ul><li><a href="https://www.quebec.ca/gouvernement/travailler-gouvernement/emplois-fonction-publique" target="_blank" rel="noreferrer">Québec.ca — emplois dans la fonction publique</a></li><li><a href="https://www.quebec.ca/emploi/trouver-emploi-stage/consulter-offres-emplois" target="_blank" rel="noreferrer">Québec.ca — consulter des offres d&#39;emploi</a></li></ul><h4 id="sites-d-offres-d-emploi" tabindex="-1">Sites d&#39;offres d&#39;emploi <a class="header-anchor" href="#sites-d-offres-d-emploi" aria-label="Permalink to &quot;Sites d&#39;offres d&#39;emploi&quot;">​</a></h4><ul><li><a href="https://www.espresso-jobs.com/" target="_blank" rel="noreferrer">Espresso-Jobs</a></li><li><a href="https://ca.indeed.com/" target="_blank" rel="noreferrer">Indeed Canada</a></li><li><a href="https://fr.glassdoor.ca/index.htm" target="_blank" rel="noreferrer">Glassdoor Canada</a></li><li><a href="https://fr.linkedin.com/company/linkedin/jobs/" target="_blank" rel="noreferrer">LinkedIn Jobs</a></li></ul><h2 id="ce-qu-on-cherche" tabindex="-1">Ce qu&#39;on cherche <a class="header-anchor" href="#ce-qu-on-cherche" aria-label="Permalink to &quot;Ce qu&#39;on cherche&quot;">​</a></h2><p>Quand vous faites une recherche, essayez de répondre à des questions simples :</p><ul><li>Quelle est la profession ou le poste visé ?</li><li>Dans quel milieu de travail retrouve-t-on ce poste ?</li><li>Quelles tâches sont associées à ce poste ?</li><li>Quelles compétences semblent demandées ?</li><li>Quelles entreprises de la région de Québec embauchent dans ce domaine ?</li></ul><h2 id="reconnaitre-une-source-fiable" tabindex="-1">Reconnaître une source fiable <a class="header-anchor" href="#reconnaitre-une-source-fiable" aria-label="Permalink to &quot;Reconnaître une source fiable&quot;">​</a></h2><p>Une source n&#39;est pas fiable seulement parce qu&#39;elle arrive en premier dans les résultats de recherche.</p><p>Avant d&#39;utiliser une information, demandez-vous :</p><ul><li>qui publie cette information</li><li>pourquoi elle est publiée</li><li>si elle est récente</li><li>si elle correspond vraiment au sujet recherché</li><li>si une autre source permet de la confirmer</li></ul><p>Exemple de source fiable :</p><ul><li>un article publié sur le site officiel de CGI : <a href="https://www.cgi.com/fr/blogue/intelligence-artificielle/optimisation-ia-generative-informatique-quantique-accelerer-simplifier-processus-decisionnels-complexes-chaine-approvisionnement" target="_blank" rel="noreferrer">Optimisation par l&#39;IA générative et l&#39;informatique quantique</a>, parce qu&#39;il s&#39;agit d&#39;un contenu provenant directement de l&#39;entreprise et lié à son domaine d&#39;activité</li></ul><p>Exemple de source moins fiable :</p><ul><li>une discussion Reddit comme <a href="https://www.reddit.com/r/france/comments/13c5obs/estce_que_lia_est_un_danger_pour_nos_m%C3%A9tiers_et/" target="_blank" rel="noreferrer">ce fil de discussion</a>, parce qu&#39;il s&#39;agit d&#39;opinions ou de témoignages non vérifiés, sans garantie de rigueur ni de représentativité</li></ul><h2 id="utiliser-l-ia-generative-pour-la-recherche" tabindex="-1">Utiliser l&#39;IA générative pour la recherche <a class="header-anchor" href="#utiliser-l-ia-generative-pour-la-recherche" aria-label="Permalink to &quot;Utiliser l&#39;IA générative pour la recherche&quot;">​</a></h2><p>De plus en plus de personnes utilisent des outils d&#39;IA générative pour commencer une recherche.</p><p>Un des outils qui sera démontré est <strong><a href="https://notebooklm.google/" target="_blank" rel="noreferrer">NotebookLM</a></strong>, qui peut aider à regrouper des sources, à résumer de l&#39;information et à faire ressortir des éléments importants à partir des documents consultés.</p><p>Cela peut être utile pour :</p><ul><li>trouver des mots-clés</li><li>repérer des pistes de recherche</li><li>obtenir un premier résumé d&#39;un sujet</li><li>comparer rapidement ce que disent plusieurs sources</li></ul><p>Par contre, les bons réflexes restent les mêmes.</p><p>Une réponse générée par l&#39;IA ne doit pas être acceptée automatiquement comme vraie.</p><h2 id="bons-reflexes" tabindex="-1">Bons réflexes <a class="header-anchor" href="#bons-reflexes" aria-label="Permalink to &quot;Bons réflexes&quot;">​</a></h2><ul><li>vérifiez toujours les sources en cliquant dessus</li><li>assurez-vous que les sources existent vraiment</li><li>vérifiez que les sources disent réellement ce que le résumé affirme</li><li>comparez l&#39;information avec d&#39;autres sources fiables</li></ul><p>Si l&#39;outil ne cite pas clairement ses sources, il n&#39;y a <strong>aucune façon de confirmer</strong> si l&#39;information est véridique.</p><p>L&#39;IA peut aider à la recherche, mais elle ne remplace pas la vérification. Vérifiez et choisissez toutes vos sources sans aucune exception.</p><h2 id="diversifier-l-information-recueillie" tabindex="-1">Diversifier l&#39;information recueillie <a class="header-anchor" href="#diversifier-l-information-recueillie" aria-label="Permalink to &quot;Diversifier l&#39;information recueillie&quot;">​</a></h2><p>Une seule source donne rarement un portrait complet.</p><p>Essayez de combiner :</p><ul><li>une source sur l&#39;entreprise</li><li>une source sur le poste</li><li>une source sur le domaine</li></ul><p>Cette diversité aide à éviter les descriptions trop vagues ou trop promotionnelles.</p><h2 id="utiliser-les-outils-de-recherche-correctement" tabindex="-1">Utiliser les outils de recherche correctement <a class="header-anchor" href="#utiliser-les-outils-de-recherche-correctement" aria-label="Permalink to &quot;Utiliser les outils de recherche correctement&quot;">​</a></h2><p>Quelques bons réflexes :</p><ul><li>cherchez avec des mots-clés précis</li><li>testez plusieurs formulations</li><li>comparez plusieurs résultats</li><li>notez vos sources au fur et à mesure</li></ul><p>Exemples de recherches utiles :</p><ul><li>développeur d&#39;application Québec</li><li>entreprise cybersécurité Québec carrières</li><li>analyste-programmeur offre d&#39;emploi Québec</li></ul><h2 id="ce-qu-il-faut-eviter" tabindex="-1">Ce qu&#39;il faut éviter <a class="header-anchor" href="#ce-qu-il-faut-eviter" aria-label="Permalink to &quot;Ce qu&#39;il faut éviter&quot;">​</a></h2><ul><li>prendre la première source sans vérification</li><li>se fier à une seule page Web</li><li>utiliser une source trop vague ou non attribuée</li><li>copier du texte sans avoir validé l&#39;information</li></ul><h2 id="activite" tabindex="-1">Activité <a class="header-anchor" href="#activite" aria-label="Permalink to &quot;Activité&quot;">​</a></h2><p>Dans le cadre de votre travail pratique, vous devrez trouver des sources pertinentes. Choisissez une des trois entreprises que vous aurez à analyser et effectuez les tâches suivantes:</p><p>Trouvez trois sources différentes :</p><ol><li>une source sur l&#39;entreprise;</li><li>une source sur un poste en informatique lié à cette entreprise;</li><li>une source plus générale sur le secteur d&#39;activité (financier, secteur public, commerce, etc.) de l&#39;entreprise.</li></ol>',53)])])}const m=r(t,[["render",a]]);export{h as __pageData,m as default};
